using System;
using System.Collections.Generic;
using ActRoguelike.Abilities;
using ActRoguelike.Config;
using ActRoguelike.Run;
using Godot;

namespace ActRoguelike.Combat;

/// <summary>
/// 单位移动能力组件（执行文档 §4.4）。挂在 Unit 节点下，只负责物理与朝向，不做任何决策：
/// 玩家控制器、敌人 Behavior 都通过 <see cref="SetIntent"/> 表达“想怎么走”。
/// 具备跳跃能力不代表 AI 会主动使用它 —— 是否调用 <see cref="TryJump"/> 由行为决定。
/// </summary>
public partial class CharacterMovement : Node
{
	private readonly List<Ability> _movementAbilities = new();
	public void RegisterAbility(Ability ability) { if (!_movementAbilities.Contains(ability)) _movementAbilities.Add(ability); }
	public void UnregisterAbility(Ability ability) => _movementAbilities.Remove(ability);
	/// <summary>允许移动攻击的被动可配置主动移速；只影响输入，不削减技能位移或外力。</summary>
	public float ActionMovementSpeedScale
	{
		get
		{
			bool attacking = false;
			float scale = 1f;
			foreach (var ability in _movementAbilities)
			{
				if (!IsInstanceValid(ability) || !ability.Enabled) continue;
				if (ability.IsBusy && ability.ActionMovement == Ability.MovementPolicy.Attack) attacking = true;
				if (ability is AirJumpPassiveAbility { GrantAttackMovement: true } agility)
					scale = Mathf.Min(scale, Mathf.Clamp(agility.AttackMoveSpeedScale, 0.05f, 1f));
			}
			return attacking ? scale : 1f;
		}
	}
	/// <summary>只限制地面主动输入；空中、技能自身位移和外力仍由原运动流程消费。</summary>
	public bool IsActionMovementLocked
	{
		get
		{
			if (_unit == null || _body == null || !_body.IsOnFloor()) return false;
			bool movingAttack = false;
			foreach (var ability in _movementAbilities)
				if (IsInstanceValid(ability) && ability is AirJumpPassiveAbility { Enabled: true, GrantAttackMovement: true }) movingAttack = true;
			foreach (var ability in _movementAbilities)
			{
				if (!IsInstanceValid(ability) || !ability.Enabled || !ability.IsBusy) continue;
				if (ability.ActionMovement == Ability.MovementPolicy.Allowed) continue;
				if (ability.ActionMovement == Ability.MovementPolicy.Attack && movingAttack) continue;
				return true;
			}
			return false;
		}
	}
	[Export] public float GravityScale { get; set; } = 1.8f;
	[Export] public float MaxFallSpeed { get; set; } = 60f;
	[Export] public float GroundAcceleration { get; set; } = 60f;
	[Export] public float AirAcceleration { get; set; } = 15f;
	[Export] public float JumpVelocity { get; set; } = 6.5f;
	/// <summary>额外空中跳的高度比例，玩家从角色表覆盖；其它单位保留原跳高。</summary>
	[Export] public float AirJumpHeightRatio { get; set; } = 1f;
	public float StandardJumpHeight => JumpVelocity * JumpVelocity / (2 * Mathf.Max(0.001f, _gravity * GravityScale));
	public float EffectiveAirJumpVelocity => EffectiveJumpVelocity * Mathf.Sqrt(Mathf.Max(0, AirJumpHeightRatio));

	/// <summary>落地后可用的额外空中跳跃次数（0 = 不能二段跳）。</summary>
	[Export] public int ExtraAirJumps { get; set; }

	/// <summary>
	/// 当前**还剩几次空中跳跃**（落地时会被重置成 <see cref="ExtraAirJumps"/>）。
	/// 滞空（角色 A 技能 2「跃升」）要判"当有跳跃次数时会先执行跳跃"，读的就是它。
	/// </summary>
	public int AirJumpsLeft => TeleportJumpEnabled ? 0 : _airJumpsLeft;
	/// <summary>额外次数只用于提高瞬移跳高，不再提供空中跳。</summary>
	public bool TeleportJumpEnabled { get; private set; }
	public int TeleportJumpCount { get; private set; }
	public float LastTeleportJumpHeight { get; private set; }
	public float TeleportJumpHeightMultiplier { get; private set; }
	public float TeleportJumpHoverSeconds { get; private set; }
	private bool _teleportJumpConsumed, _teleportAwaitAir;
	public void ConfigureTeleportJump(bool enabled, float heightMultiplier = 0, float hoverSeconds = 0)
	{
		TeleportJumpEnabled = enabled;
		TeleportJumpHeightMultiplier = heightMultiplier;
		TeleportJumpHoverSeconds = hoverSeconds;
		TeleportJumpCount = 0;
		LastTeleportJumpHeight = 0f;
		_teleportJumpConsumed = _teleportAwaitAir = false;
		if (enabled) _airJumpsLeft = 0;
	}

	/// <summary>
	/// **额外跳跃次数的接入点**（被动「灵动」/ 异化「践踏死亡」这类"在空中额外跳跃"的效果走这里）。
	///
	/// <para>用户的设计文档（角色 A 被动「灵动」）：「角色能在空中额外跳跃一次（正常情况下所有角色都
	/// 只会有 1 次额外的获取方法，**上限最多 3 次**）」—— 所以上限是参数、不是常量：
	/// 上限值由调用方（表驱动的那条被动/异化）传进来。</para>
	///
	/// <para>⚠️ 它是**幂等的写入**：调用方每帧算出的目标值一样时这里什么都不做（不会每次重置空中次数），
	/// 落地时仍然由 <see cref="_PhysicsProcess"/> 那行按 <see cref="ExtraAirJumps"/> 回满。</para>
	/// </summary>
	public void SetExtraAirJumps(int value, int cap)
	{
		int wanted = Mathf.Clamp(value, 0, Mathf.Max(0, cap));
		if (wanted == ExtraAirJumps)
		{
			return;
		}

		ExtraAirJumps = wanted;
		_airJumpsLeft = Mathf.Min(_airJumpsLeft, wanted);
	}

	/// <summary>击杀等一次性授予同时增加容量与立即可用次数；满容量后仍可补回，不减少其他来源已有次数。</summary>
	public void GrantAirJumps(int amount, int cap)
	{
		if (amount <= 0 || cap <= 0) return;
		ExtraAirJumps = Mathf.Max(ExtraAirJumps, Mathf.Min(ExtraAirJumps + amount, cap));
		_airJumpsLeft = Mathf.Max(_airJumpsLeft, Mathf.Min(_airJumpsLeft + amount, Mathf.Min(ExtraAirJumps, cap)));
	}

	/// <summary>击退等外力的衰减速度（1/秒）。</summary>
	[Export] public float ImpulseDamping { get; set; } = 6f;

	[Export] public bool FaceMovementDirection { get; set; } = true;
	[Export] public float TurnSharpness { get; set; } = 14f;

	private CharacterBody3D _body = null!;
	private Unit? _unit;
	private AirHoverController? _hover;
	private float _gravity;

	private Vector3 _intentDirection;
	private float _intentSpeed;
	private Vector3 _inputVelocity;
	private Vector3 _externalVelocity;
	private Vector3 _facing;
	private bool _hasFacing;
	private int _airJumpsLeft;
	private Vector3 _dashDirection;
	private float _dashSpeed;
	private object? _velocityOverrideSource;
	private Vector3 _overrideVelocity;
	private float _overrideTimeLeft = -1;
	private bool _overrideIsDash;
	private bool _overridePlanarOnly;
	public bool HasVelocityOverride => _velocityOverrideSource != null;
	public bool VelocityOverrideFinished(object source) => ReferenceEquals(source, _velocityOverrideSource) && _overrideTimeLeft == 0;

	/// <summary>动作持有完整三维速度；结束时只能释放自己持有的覆盖。</summary>
	public bool BeginVelocityOverride(object source, Vector3 velocity, float duration = -1, bool isDash = false, bool planarOnly = false)
	{
		if (IsControlDisabled || _unit?.HasActionLock == true) return false;
		if (_velocityOverrideSource != null && !ReferenceEquals(_velocityOverrideSource, source)) return false;
		_velocityOverrideSource = source;
		_overrideVelocity = velocity;
		_overrideTimeLeft = duration;
		_overrideIsDash = isDash;
		_overridePlanarOnly = planarOnly;
		return true;
	}
	public void EndVelocityOverride(object source)
	{
		if (!ReferenceEquals(_velocityOverrideSource, source)) return;
		_velocityOverrideSource = null;
		_overrideVelocity = Vector3.Zero;
		_overrideTimeLeft = -1;
		_overrideIsDash = false;
		_overridePlanarOnly = false;
		_inputVelocity = Vector3.Zero;
		if (IsInstanceValid(_body)) _body.Velocity = Vector3.Zero;
		_previousExternalY = 0f;
	}

	public bool IsGrounded => _body.IsOnFloor();
	public Vector3 PlanarVelocity { get { Vector3 v = _body.Velocity; v.Y = 0f; return v; } }

	/// <summary>
	/// **本段滞空已经"净下落"了多少米**（P4 新增，只加不删）：从这次离地开始记录**最高点**，
	/// 之后每帧算 <c>最高点.Y - 当前.Y</c>（夹在 ≥0）。落到地面时最后一次 <see cref="_PhysicsProcess"/>
	/// 里仍然是"落地前那一帧"的值，所以"落地时的下落高度"读得到。
	///
	/// <para>该量保留给实际下落距离的观察者；共通落已按用户裁定改读起手脚下到World地面高度。</para>
	///
	/// <para>⚠️ 默认（没有任何技能读它）行为逐位不变：它只在一处多算了两个浮点量，
	/// 不参与 <c>MoveAndSlide</c> 的任何输入。</para>
	/// </summary>
	public float FallHeight { get; private set; }

	private float _apexY;
	private bool _apexTracking;

	public bool IsAirborne => _body != null && !_body.IsOnFloor();

	/// <summary>当前的移动意图方向（未归一化前的原样），位移技能用它决定冲刺方向。</summary>
	public Vector3 IntentDirection => _intentDirection;

	public bool IsDashing => _dashSpeed > 0f || (HasVelocityOverride && _overrideIsDash);

	private readonly HashSet<object> _facingLocks = new(ReferenceEqualityComparer.Instance);
	/// <summary>技能按自身所有权锁定转身；例如后撤期间转镜头也不改变起手朝向。</summary>
	public bool IsFacingLocked => _facingLocks.Count > 0;
	public void LockFacing(object source) => _facingLocks.Add(source);
	public void UnlockFacing(object source) => _facingLocks.Remove(source);

	/// <summary>位移技能用：在持续时间内以固定速度沿方向移动，忽略常规加速度。</summary>
	public void BeginDash(Vector3 direction, float speed)
	{
		if (IsControlDisabled || _unit?.HasActionLock == true) return;
		_dashDirection = direction.LengthSquared() < 0.0001f ? -_body.GlobalTransform.Basis.Z : direction.Normalized();
		_dashSpeed = speed;
	}

	public void EndDash()
	{
		if (_dashSpeed <= 0) return;
		_dashSpeed = 0f;
		// 强制冲刺结束后归还普通移动，不能把上一帧冲刺速度当作输入惯性继续滑行。
		_inputVelocity = Vector3.Zero;
	}

	/// <summary>位移/扑击技能用：直接设置垂直速度。</summary>
	public void SetVerticalVelocity(float velocity)
	{
		Vector3 v = _body.Velocity;
		v.Y = velocity;
		_body.Velocity = v;
		_previousExternalY = 0f;
	}
	/// <summary>成功的主动起跳事实，携带起跳前圆心；落地、击退和单纯离地不产生此事件。</summary>
	public event Action<Vector3>? JumpStarted;
	public void BeginJump(float velocity)
	{
		if (_unit?.HasActionLock == true) return;
		SetVerticalVelocity(velocity);
		if (velocity > 0f) JumpStarted?.Invoke(_body.GlobalPosition);
	}

	public override void _Ready()
	{
		_body = GetParent<CharacterBody3D>();
		_unit = _body as Unit;
		_hover = _unit?.GetNodeOrNull<AirHoverController>("AirHover");
		// 初始只收集一次；后加的能力由Ability注册，避免每物理帧遍历模型整棵子树。
		if (_unit != null) NodeSearch.CollectInSubtree(_unit, _movementAbilities);
		_gravity = ProjectSettings.GetSetting("physics/3d/default_gravity").AsSingle();
		if (_unit != null)
		{
			_unit.KnockbackReceived += OnKnockback;

			// ⚠️ **必须 defer 一帧**：归属组（`player_units` / `enemy_units`）是在 `Unit._Ready` 里
			// `AddToGroup` 的，而**子节点的 `_Ready` 早于父节点** —— 在 `_Ready` 里问 `IsInGroup`
			// 拿到的永远是 false（首轮实测：12 个单位全是 `player_units 组=False`，跳跃配置一次都没生效）。
			// defer 的调用排在当前帧所有 `_Ready` 之后，这时组已经登记好了。
			CallDeferred(nameof(ApplyJumpConfigDeferred));
		}
	}

	/// <summary>
	/// 跳跃参数来自**角色表**（`Config/Tables/Characters/chr_*.tres` 的「跳跃」两组）——
	/// 玩家预制体（`Player.tscn` 的 <c>Movement</c>）只保留 <c>JumpVelocity</c> / <c>GravityScale</c> 作为**回退值**。
	///
	/// ⚠️ **只有玩家读表**：表里那两列写的是"玩家手感"。敌人 / 召唤物的跳跃（如 `JumpingMelee.tscn`
	/// 的 <c>JumpVelocity = 9</c>）留在各自场景上，否则调玩家的跳跃会连带改掉 9 个敌种的扑击高度。
	/// 组判定按 `player_units`（`Unit._Ready` 里登记）。
	///
	/// ⚠️ 与 <see cref="UnitConfig.ApplyTo"/> 那条路径（实例化 → ApplyTo → AddChild）不同：
	/// 这里就地解析（按玩家 <c>RunSetup.Character</c> 选行、读不到行就什么都不做）。同理，
	/// 玩家在中途换角色不会重新算 —— <c>RunController.ApplyBalance</c> 换角色时会重建这一份数值，
	/// 而那属于它的文件边界（本轮不碰）。
	///
	/// <b>2026-10-12 用户拍板（需求 A2）：去掉倍率运算，改成"直接改固定值"</b> ——
	/// 原来这里是 <c>JumpHeightMultiplier</c>（按平方根换算高度）+ <c>JumpSpeedMultiplier</c>
	/// （乘在 <c>AirAcceleration</c> / <c>MaxFallSpeed</c> 上）两个旋钮，用户要的是
	/// 「**直接改固定值**…**起跳速度也要快**」。现在表里给的就是绝对值：
	/// 起跳速度直接写进 <see cref="JumpVelocity"/>、重力缩放直接写进 <see cref="GravityScale"/>，
	/// 空中加速与最大下落**不再被乘任何倍率**（保持场景里的值）。
	/// </summary>
	private void ApplyJumpConfigDeferred()
	{
		if (_unit == null || !IsInstanceValid(_unit))
		{
			return;
		}

		// 只有玩家读表（按组判定）。
		if (!_unit.IsInGroup("player_units"))
		{
			return;
		}

		if (ConfigRows.BySlot<CharacterConfig>((int)RunSetup.Character + 1) is not { } row)
		{
			// 表读不到 → 保留场景里的值（"读不到则使用自身的默认值"），但必须留痕，否则"跳跃没变"会查不出来。
			ActRoguelike.Core.GameLog.Write(
				"Config",
				$"跳跃：角色行读不到（RunSetup.Character={RunSetup.Character} / 角色表 {ConfigRows.Count<CharacterConfig>()} 行）→ 起跳速度保持场景值 {JumpVelocity:0.##} m/s / 重力缩放 {GravityScale:0.##}");
			return;
		}

		// 直接改固定值（用户需求 A2：不要倍率、不要"逻辑运算"）。
		row.ApplyJumpTo(this);

		ActRoguelike.Core.GameLog.Write(
			"Config",
			$"跳跃：角色行 {row.Id} → 起跳速度 {JumpVelocity:0.##} m/s / 重力缩放 {GravityScale:0.##}（两列都是**固定值**、直接套用，没有任何倍率运算）｜ 空中加速 {AirAcceleration:0.#} / 最大下落 {MaxFallSpeed:0.#} 保持场景值（来源：表 Characters，读不到则用场景导出值）");
	}

	public override void _ExitTree()
	{
		_forces.Clear(); _heightLimits.Clear();
		_movementAbilities.Clear();
		if (_unit != null)
		{
			_unit.KnockbackReceived -= OnKnockback;
		}
	}

	/// <summary>设置水平移动意图。direction 不需要归一化，speed 为 0 即停下。</summary>
	public void SetIntent(Vector3 direction, float speed)
	{
		if (_unit?.HasActionLock == true) { Stop(); return; }
		_intentDirection = direction.LengthSquared() > 1f ? direction.Normalized() : direction;
		_intentSpeed = speed;
	}

	public void Stop()
	{
		_intentDirection = Vector3.Zero;
		_intentSpeed = 0f;
	}

	/// <summary>强制朝向（例如瞄准方向）；传零向量即恢复按移动方向转身。</summary>
	public void SetFacing(Vector3 direction)
	{
		_facing = direction;
		_hasFacing = direction.LengthSquared() > 0.0001f;
	}

	/// <summary>
	/// **实际起跳速度** = 表里的固定值 × 单位级 <c>JumpVelocityMultiplier</c>（强化「攀高」给单位挂这个修正器）。
	///
	/// <para>⚠️ 键没有基础值时按 **1** 算（`Unit.SeedStats` 里已经给了基础值 1；这里再兜一层，
	/// 免得少一个基础值就变成"跳不起来"）—— 这是 `architecture.md` 第 8 条那条纪律。
	/// 没人配置时逐位等于 <see cref="JumpVelocity"/>，所以 P6 之前的跳跃行为一位没变。</para>
	/// </summary>
	public float EffectiveJumpVelocity
	{
		get
		{
			float multiplier = _unit?.Stats.Get("JumpVelocityMultiplier") ?? 1f;
			return JumpVelocity * (multiplier > 0f ? multiplier : 1f);
		}
	}

	public bool TryJump()
	{
		if (CanFly || IsControlDisabled || _unit?.HasActionLock == true) return false;
		if (HasVelocityOverride) return false;
		if (TeleportJumpEnabled) return TryTeleportJump();
		if (_body.IsOnFloor())
		{
			BeginJump(EffectiveJumpVelocity);
			return true;
		}

		if (_airJumpsLeft > 0)
		{
			_airJumpsLeft--;
			BeginJump(EffectiveAirJumpVelocity);
			return true;
		}

		return false;
	}

	private bool TryTeleportJump()
	{
		if (!_body.IsOnFloor() || _teleportJumpConsumed) return false;
		// 每份额外次数换一份完整地面跳高，不能套普通空中跳的0.5高度比例。
		float height = TeleportJumpHeightMultiplier > 0 ? StandardJumpHeight * TeleportJumpHeightMultiplier
			: EffectiveJumpVelocity * EffectiveJumpVelocity / (2f * Mathf.Max(0.001f, _gravity * GravityScale)) * (1 + Mathf.Max(0, ExtraAirJumps));
		using var collision = new KinematicCollision3D();
		float travel = _body.TestMove(_body.GlobalTransform, Vector3.Up * height, collision)
			? Mathf.Clamp(collision.GetTravel().Y, 0f, height) : height;
		// 净空不足以离开地面吸附范围时不消耗本次跳跃，避免卡在旧地面状态。
		if (travel <= Mathf.Max(0.001f, _body.FloorSnapLength + 0.002f)) return false;
		Vector3 origin = _body.GlobalPosition;
		_body.GlobalPosition += Vector3.Up * travel;
		_body.ResetPhysicsInterpolation();
		_body.Velocity = _body.Velocity with { Y = 0f };
		_externalVelocity.Y = 0f;
		_previousExternalY = 0f;
		_airJumpsLeft = 0;
		_teleportJumpConsumed = _teleportAwaitAir = true;
		_apexY = _body.GlobalPosition.Y;
		_apexTracking = true;
		FallHeight = 0f;
		LastTeleportJumpHeight = travel;
		TeleportJumpCount++;
		if (TeleportJumpHoverSeconds > 0) _unit?.GetNodeOrNull<AirHoverController>("AirHover")?.Grant(TeleportJumpHoverSeconds);
		JumpStarted?.Invoke(origin);
		ActRoguelike.Core.GameLog.Write("Combat", $"浮光跃金：目标{height:0.###}m／实际瞬移{travel:0.###}m，浮空{TeleportJumpHoverSeconds:0.##}秒");
		return true;
	}

	public void AddImpulse(Vector3 impulse) { if (impulse.IsFinite()) _externalVelocity += impulse; }

	private void OnKnockback(Vector3 impulse)
	{
		if (!IsControlImmune) ApplyPhysicalImpulse(impulse * (1f - Mathf.Clamp(_unit?.KnockbackResistance ?? 0f, 0f, 1f)));
	}

	public override void _PhysicsProcess(double delta)
	{
		using var frameProfile=ActRoguelike.Core.RuntimeFrameProfiler.Measure("Movement");
		if (_unit?.ImpactPause?.IsHolding == true) return;
		float dt = (float)delta;
		if (_unit is { IsDead: true })
		{
			return;
		}

		Vector3 velocity = _body.Velocity;
		// 上帧外力仅作为速度组成项，不能再次加到垂直基础速度形成正反馈。
		velocity.Y -= _previousExternalY;
		StepPhysicsEffects(dt);
		bool flying = ApplyFlightLift(ref velocity, dt);

		if (_body.IsOnFloor())
		{
			if (!_teleportAwaitAir) _teleportJumpConsumed = false;
			_airJumpsLeft = TeleportJumpEnabled ? 0 : ExtraAirJumps;
			// 落地：这次的"最高点"追踪结束（FallHeight 保留最后一次的值，落地那一帧仍然读得到）。
			_apexTracking = false;
		}
		else if (!flying)
		{
			_teleportAwaitAir = false;
			// ⭐ J11：正常下落速度上限的单位级倍率（符文「飞翼」= 降低正常下落速度）。
			// 基础值 1（`Unit.SeedStats`），`-MaxFallSpeed × 1.0f` 与改动前逐位相等；
			// 只在**正常下落**这一段生效 —— 下落攻击 / 冲刺那些走 VelocityOverride，不受它影响。
			float fallScale = _unit?.Stats.Get("MaxFallSpeedMultiplier") ?? 1f;
			float fallCap = fallScale > 0f ? MaxFallSpeed * fallScale : MaxFallSpeed;
			velocity.Y = Mathf.Max(velocity.Y - _gravity * GravityScale * dt, -fallCap);
			// P4：滞空期间维护"最高点"（离地即开始，落地结束）。
			float nowY = _body.GlobalPosition.Y;
			if (!_apexTracking)
			{
				_apexTracking = true;
				_apexY = nowY;
			}
			else
			{
				_apexY = Mathf.Max(_apexY, nowY);
			}

			FallHeight = Mathf.Max(0f, _apexY - nowY);
		}

		if (HasVelocityOverride && _unit?.Reactions?.IsStaggered != true && _unit?.HasActionLock != true)
		{
			float fraction = _overrideTimeLeft < 0 ? 1 : Mathf.Clamp(_overrideTimeLeft / Mathf.Max(0.000001f, dt), 0, 1);
			_body.Velocity = _overrideVelocity * fraction;
			if (_overridePlanarOnly)
				_body.Velocity = new Vector3(_body.Velocity.X, velocity.Y, _body.Velocity.Z) + _externalVelocity;
			_body.Velocity += _crowdVelocity;
			_body.MoveAndSlide();
			if (_overridePlanarOnly) FinishPhysicsMove(Mathf.Max(0, -_body.Velocity.Y));
			else { ClipCrowdPush(); _previousExternalY = 0f; }
			if (_overrideTimeLeft >= 0)
			{
				_overrideTimeLeft = Mathf.Max(0, _overrideTimeLeft - dt);
				if (_overrideTimeLeft < 0.000001f) _overrideTimeLeft = 0;
			}
			if (FaceMovementDirection) FaceDirection(_hasFacing ? _facing : _overrideVelocity, dt);
			return;
		}

		// 输入速度单独维护：不能从刚体速度里读回来，否则击退会叠加上一帧的击退形成正反馈。
		Vector3 planar;
		if (_dashSpeed > 0f && !IsControlDisabled && _unit?.HasActionLock != true)
		{
			planar = _dashDirection * _dashSpeed;
			_inputVelocity = planar;
		}
		else if (IsActionMovementLocked || IsControlDisabled || _unit?.HasActionLock == true)
		{
			// 进入锁定动作立即收住主动惯性；不清外力，避免抵消击退或技能突进。
			_inputVelocity = planar = Vector3.Zero;
		}
		else
		{
			float speedMultiplier = _unit?.Stats.Get("MoveSpeedMultiplier") ?? 1f;
			float actionScale = ActionMovementSpeedScale;
			// 浮空只改主动输入：忽略奔跑和成长倍率，技能位移与外力仍走原通道。
			bool fixedHoverSpeed = !_body.IsOnFloor() && _hover is { IsHovering: true, Maintaining: true }
				&& (string.IsNullOrEmpty(_hover.CancelAction) || !Input.IsActionJustPressed(_hover.CancelAction));
			float desiredSpeed = fixedHoverSpeed ? (_intentSpeed > 0 ? (_unit?.MoveSpeed ?? 0) * .5f : 0) : _intentSpeed * speedMultiplier * actionScale;
			// 进入攻击时即时限制主动惯性，避免从奔跑带着高速滑过蓄力前段。
			if ((fixedHoverSpeed || actionScale < 1f) && _inputVelocity.Length() > desiredSpeed)
				_inputVelocity = _inputVelocity.Normalized() * Mathf.Max(0f, desiredSpeed);
			Vector3 desired = _intentDirection * desiredSpeed;
			float acceleration = (_body.IsOnFloor() ? GroundAcceleration : AirAcceleration) * dt;
			_inputVelocity = _inputVelocity.MoveToward(desired, acceleration);
			_inputVelocity = _unit?.Navigation?.Avoid(_inputVelocity) ?? _inputVelocity;
			planar = _inputVelocity;
		}

		velocity.X = planar.X + _externalVelocity.X + _crowdVelocity.X;
		velocity.Z = planar.Z + _externalVelocity.Z + _crowdVelocity.Z;
		velocity.Y += _externalVelocity.Y;
		_body.Velocity = velocity;
		_body.MoveAndSlide();
		FinishPhysicsMove(Mathf.Max(0f, -velocity.Y));

		if (!FaceMovementDirection)
		{
			return;
		}

		Vector3 face = _hasFacing ? _facing : planar;
		FaceDirection(face, dt);
	}

	public void FaceDirection(Vector3 direction, float dt)
	{
		if (IsFacingLocked) return;
		direction.Y = 0f;
		if (direction.LengthSquared() < 0.04f)
		{
			return;
		}

		float targetYaw = Mathf.Atan2(-direction.X, -direction.Z);
		float weight = 1f - Mathf.Exp(-TurnSharpness * dt);
		_body.Rotation = new Vector3(0f, Mathf.LerpAngle(_body.Rotation.Y, targetYaw, weight), 0f);
	}
}

Scripts/Camera/CameraRig.cs.text:
using Godot;
using ActRoguelike.Abilities;
using ActRoguelike.Combat;

namespace ActRoguelike.Camera;

/// <summary>
/// 第三人称镜头预制体（执行文档 6.2 的独立 CameraRig 方案）。
/// 结构：CameraRig(Yaw) -> SpringArm3D(Pitch/碰撞) -> Camera3D。
/// 设为 TopLevel，因此不继承目标节点的旋转，位置由本脚本跟随 <see cref="Target"/>。
/// 俯角约定：PitchDegrees 为正表示镜头在目标上方俯视。
/// </summary>
public partial class CameraRig : Node3D
{
	[Export] public Node3D? Target { get; set; }

	[Export(PropertyHint.Range, "0.02,2,0.01")] public float MouseSensitivity { get; set; } = 0.25f;

	[Export] public float MinPitchDegrees { get; set; } = -70f;
	[Export] public float MaxPitchDegrees { get; set; } = 70f;

	[Export(PropertyHint.Range, "-70,70,1")] public float PitchDegrees { get; set; } = 20f;

	/// <summary>镜头围绕目标的位置偏移，通常取角色胸口高度。</summary>
	[Export] public Vector3 TargetOffset { get; set; } = new(0f, 1.5f, 0f);

	/// <summary>
	/// 角色在屏幕上的高度比例（0.5 = 正中，越小角色越靠下）。
	/// 第三人称常用 0.25~0.35：角色偏下，视野更多留给前方。
	/// </summary>
	[Export(PropertyHint.Range, "0.05,0.5,0.01")] public float TargetScreenHeight { get; set; } = 0.3f;

	/// <summary>跟随平滑速度（1/秒）。越大越紧跟，0 表示硬跟随。</summary>
	[Export] public float FollowSharpness { get; set; } = 12f;

	[Export] public bool CaptureMouseOnStart { get; set; } = true;
	/// <summary>长枪按住输入预览时向右肩平移，给完整抛物线留出侧向视差。</summary>
	[Export] public float SpearShoulderOffset { get; set; } = .95f;
	[Export] public float ShoulderBlendSpeed { get; set; } = 8f;
	public float ShoulderOffset { get; private set; }
	public bool ShoulderPreviewActive { get; private set; }

	private SpringArm3D _springArm = null!;
	private float _yawDegrees;

	/// <summary>镜头水平前方向（已归一化），供单位移动与瞄准使用。</summary>
	public Vector3 FlatForward => Flatten(-GlobalTransform.Basis.Z);

	/// <summary>镜头水平右方向（已归一化）。</summary>
	public Vector3 FlatRight => Flatten(GlobalTransform.Basis.X);

	/// <summary>收到过的鼠标移动事件数（排查「UI 抢走视角输入」用）。</summary>
	public int MouseMotionEvents { get; private set; }

	/// <summary>鼠标当前是否被捕获（只有捕获状态下才会转动视角）。</summary>
	public bool IsMouseCaptured => Input.MouseMode == Input.MouseModeEnum.Captured;

	public override void _Ready()
	{
		TopLevel = true;
		_springArm = GetNode<SpringArm3D>("SpringArm");
		_springArm.CollisionMask = ActRoguelike.Combat.CombatLayers.World;
		Target ??= GetParent() as Node3D;
		if (Target is CollisionObject3D body)
		{
			_springArm.AddExcludedObject(body.GetRid());
		}

		_yawDegrees = Mathf.RadToDeg(Rotation.Y);
		ApplyRotation();

		if (CaptureMouseOnStart)
		{
			Input.MouseMode = Input.MouseModeEnum.Captured;
		}
	}

	/// <summary>
	/// 跟随目标。**必须放在 _PhysicsProcess 里**，和物理同频：
	/// 之前写在 _Process（120fps）、而角色位置只在 60Hz 物理帧上变，导致镜头与角色
	/// 「一帧动一帧不动」交替，画面上就是持续缓动 + 残影（实测：镜头单帧位移 0 与 0.06 交替，
	/// 角色/镜头相位差在 4.091~4.133 之间反复抖动）。
	/// 放到物理帧后由物理插值把它插回渲染帧，镜头与角色共享同一对物理状态，相对位置恒定。
	/// </summary>
	public override void _PhysicsProcess(double delta)
	{
		if (Target == null || !IsInstanceValid(Target))
		{
			ShoulderPreviewActive = false; ShoulderOffset = 0;
			return;
		}

		ShoulderPreviewActive = HasSpearInputPreview();
		ShoulderOffset = Mathf.MoveToward(ShoulderOffset, ShoulderPreviewActive ? SpearShoulderOffset : 0f,
			Mathf.Max(.1f, ShoulderBlendSpeed) * (float)delta);
		Vector3 desired = Target.GlobalPosition + TargetOffset + (Vector3.Up * ScreenHeightLift()) + FlatRight * ShoulderOffset;
		if (FollowSharpness <= 0f)
		{
			GlobalPosition = desired;
		}
		else
		{
			float weight = 1f - Mathf.Exp(-FollowSharpness * (float)delta);
			GlobalPosition = GlobalPosition.Lerp(desired, weight);
		}
	}

	private bool HasSpearInputPreview()
	{
		if (Target is not Unit { IsDead: false } unit || GetTree().Paused) return false;
		foreach (var slot in unit.AbilitySlots.Inputs)
		{
			// 只读当前装入槽位的输入预览；换装保护与取消仍由 PlayerAbilityInput/Ability 统一负责。
			if (unit.AbilitySlots.Resolve(slot.Key) is SpearThrowAbility { InputPreviewShowing: true }
				&& InputMap.HasAction(slot.Key) && Input.IsActionPressed(slot.Key)) return true;
		}
		return false;
	}

	/// <summary>
	/// 让角色不居中所需的抬高量：镜头看向的是 rig 原点，把它抬高一点，
	/// 角色就落在画面下方（抬高的世界距离 = 屏幕比例差 × 该距离处的视锥高度）。
	/// </summary>
	private float ScreenHeightLift()
	{
		if (TargetScreenHeight >= 0.499f)
		{
			return 0f;
		}

		Camera3D? camera = GetViewport().GetCamera3D();
		float fov = camera?.Fov ?? 75f;
		float distance = Mathf.Max(0.5f, _springArm.SpringLength);
		float viewHeight = 2f * Mathf.Tan(Mathf.DegToRad(fov * 0.5f)) * distance;
		return (0.5f - TargetScreenHeight) * viewHeight;
	}

	/// <summary>
	/// 视角走 _Input 而不是 _UnhandledInput：HUD 上任何 mouse_filter = Stop 的显示元素
	/// （准星、色块…）都会抢先吃掉鼠标事件，导致镜头完全不能转（踩过一次）。
	/// 游戏视角属于「玩家输入」，不该被纯显示的 UI 拦截。
	/// </summary>
	public override void _Input(InputEvent @event)
	{
		if (@event is InputEventMouseMotion motion)
		{
			MouseMotionEvents++;
			if (Input.MouseMode == Input.MouseModeEnum.Captured)
			{
				_yawDegrees -= motion.Relative.X * MouseSensitivity;
				PitchDegrees = Mathf.Clamp(PitchDegrees + motion.Relative.Y * MouseSensitivity, MinPitchDegrees, MaxPitchDegrees);
				ApplyRotation();
			}
		}
	}

	private void ApplyRotation()
	{
		Rotation = new Vector3(0f, Mathf.DegToRad(_yawDegrees), 0f);
		_springArm.RotationDegrees = new Vector3(-PitchDegrees, 0f, 0f);
	}

	private static Vector3 Flatten(Vector3 direction)
	{
		direction.Y = 0f;
		return direction.Normalized();
	}
}

Scripts/Run/Survival/SurvivalDirector.cs.text:
using System;
using System.Collections.Generic;
using System.Linq;
using ActRoguelike.Combat;
using ActRoguelike.Config;
using ActRoguelike.Core;
using ActRoguelike.Rewards;
using ActRoguelike.World;
using Godot;

namespace ActRoguelike.Run;

/// <summary>生存模式只编排节奏和目标；战斗、奖励、导航与结算复用正式入口。</summary>
public partial class SurvivalDirector : RunModeController
{
	public enum PhaseState { Dormant, Preparing, Surviving, FinalBoss, AwaitingExit, Stopped }
	[Export(PropertyHint.File, "*.tres")] public string DefinitionPath { get; set; } = "res://Config/Modes/twilight_survival.tres";
	public SurvivalDefinition? Definition { get; set; }
	public override string ModeId => (Definition ??= RuntimeResources.Load<SurvivalDefinition>(DefinitionPath)).Id;
	public SurvivalBuildRuntime? BuildRuntime { get; private set; }
	[Export] public bool EnableSceneRunes { get; set; } = true;
	public SceneRuneController? SceneRune { get; private set; }
	public event Action? SceneRuneChanged;
	public event Action<SurvivalExperienceReceipt>? ExperienceCollected;
	public event Action<Unit, int>? EnemyDefeated;
	public Unit[] LivingEnemies => _owned.Keys.Where(u => IsInstanceValid(u) && !u.IsDead && !u.IsQueuedForDeletion()).ToArray();
	public bool OwnsEnemy(Unit unit) => _owned.ContainsKey(unit);
	private double _experienceRemainder;
	public override string DisplayName => Definition?.Title ?? "死战";
	public PhaseState State { get; private set; }
	public bool Active => State is PhaseState.Preparing or PhaseState.Surviving or PhaseState.FinalBoss;
	public float ElapsedSeconds { get; private set; }
	public int Level { get; private set; } = 1;
	public int Experience { get; private set; }
	public int NextLevelExperience => Definition?.ExperienceForLevel(Level) ?? 1;
	public int CompletedBeacons { get; private set; }
	public int CompletedObjectives { get; private set; }
	public int PendingRewards => _rewards.Count;
	public int AliveCount => _owned.Count;
	public float AlivePressure { get; private set; }
	public int PendingSpawns => _pending.Count;
	public float SpendableBudget => _bank;
	public int TotalSpawned { get; private set; }
	public int TotalKills { get; private set; }
	public bool BossDefeated { get; private set; }
	public Unit? Player => _player;
	public Unit? Boss => _boss;
	public ExperienceField? ExperienceField => _experience;
	public IReadOnlyList<SurvivalObjective> Objectives => _objectives.AsReadOnly();
	public string Notice { get; private set; } = "准备试炼";
	public string PhaseTitle => State == PhaseState.FinalBoss ? "终局首领" : State == PhaseState.AwaitingExit ? "试炼完成 · 前往撤离门" : Definition?.Phases.ElementAtOrDefault(_phaseIndex)?.Title ?? "准备入场";
	private RunController? _run;
	private Unit? _player, _boss;
	private Node _sceneOwner = null!;
	private ExperienceField? _experience;
	private SurvivalHud? _hud;
	private readonly List<SurvivalObjective> _objectives = new();
	private readonly Queue<(RewardKind? Kind, string Title)> _rewards = new();
	private readonly HashSet<SurvivalObjective> _claimedObjectives = new();
	private bool _choicePending;
	private int _generation, _phaseIndex = -1, _milestoneIndex;
	private float _bank, _spawnTimer, _preparationTime, _scanTimer;
	private StageStatistics? _frozen;
	private ProcessModeEnum _playerProcessMode;
	private bool _heldPlayer;

	public override void Begin(RunController run, Unit player)
	{
		Stop(); _generation++; _frozen = null; _run = run; _player = player; _sceneOwner = GetParent();
		Definition ??= RuntimeResources.Load<SurvivalDefinition>(DefinitionPath);
		if (Definition == null) throw new InvalidOperationException("生存模式缺少设置。");
		string[] errors = Definition.Validate().ToArray();
		if (errors.Length > 0) throw new InvalidOperationException(string.Join("；", errors));
		ElapsedSeconds = 0; Level = 1; Experience = 0; CompletedBeacons = 0; CompletedObjectives = 0;
		_experienceRemainder = 0;
		CollectedCombatShards = DroppedCombatShards = PendingCombatShards = 0;
		TotalSpawned = 0; TotalKills = 0; BossDefeated = false; _boss = null; _phaseIndex = -1; _milestoneIndex = 0;
		_bank = 0; _spawnTimer = 0; _preparationTime = 0; _scanTimer = 0; _choicePending = false; _claimedObjectives.Clear();
		State = PhaseState.Preparing; Notice = "正在准备导航与入场点…";
		_playerProcessMode = player.ProcessMode; player.ProcessMode = ProcessModeEnum.Disabled; _heldPlayer = true;
		_experience = new ExperienceField { Name = "ExperienceField", Player = player, Capacity = Definition.MaxExperienceMotes, PickupRadius = Definition.PickupRadius };
		AddChild(_experience); _experience.Collected += GrantExperience;
		// 旧十二项死战专属已退出获取，不再安装其命中/经验协调器。
		if (EnableSceneRunes)
		{
			var selected = Definition.FixedSceneRune;
			if (selected == null)
			{
				using var random = new RandomNumberGenerator(); random.Randomize();
				float total = Definition.SceneRunePool.Sum(r => r.Weight), roll = random.Randf() * total;
				foreach (var rune in Definition.SceneRunePool) if (rune.Weight > 0 && (roll -= rune.Weight) <= 0) { selected = rune; break; }
			}
			if (selected != null) { SceneRune = new SceneRuneController { Name = "SceneRune", Definition = selected, Player = player }; AddChild(SceneRune); }
		}
		_hud = new SurvivalHud { Director = this }; AddChild(_hud);
		SceneRuneChanged?.Invoke();
	}
	public override void _PhysicsProcess(double delta)
	{
		if (!Active || _player == null || !IsInstanceValid(_player) || _player.IsDead || _run == null || _run.RunEnded) return;
		float dt = (float)delta;
		if (State == PhaseState.Preparing)
		{
			_preparationTime += dt;
			if (MapManager.Instance is { IsReady: true } map && map.TryValidPoint(new Vector3(0, .1f, 38), new Vector3(0, .1f, 38), out Vector3 start, _player))
			{
				_spawnGroundAnchor = start;
				_player.GlobalPosition = start + Vector3.Up * .08f; _player.ResetPhysicsInterpolation(); ReleasePlayer();
				for (int i = 0; i < Definition!.BeaconPositions.Length; i++)
				{
					Vector3 desired = Definition.BeaconPositions[i];
					if (!map.TryValidPoint(desired, start, out Vector3 point, _player)) throw new InvalidOperationException($"信标{i + 1}没有可达位置。");
					var beacon = new SurvivalObjective { Name = $"Beacon{i + 1}", Director = this, Kind = SurvivalObjective.ObjectiveKind.Beacon, Index = i };
					AddChild(beacon); beacon.GlobalPosition = point; _objectives.Add(beacon);
				}
				State = PhaseState.Surviving; Notice = ContentText.Get("ui.survival.objective_help", "蓝绿色圆锥＋圆环：靠近按F净化信标，启动后留在圈内。\n橙色遗物：靠近按F选择增幅。");
			}
			else if (_preparationTime > 15) { Notice = "入场准备失败，已取消本次试炼。"; _run.CancelAdventure(out _); }
			return;
		}
		ElapsedSeconds += dt; PruneUnits();
		SceneRune?.Tick(dt);
		if (!Active || _run.RunEnded || _player.IsDead) return;
		_scanTimer -= dt; if (_scanTimer <= 0) { _scanTimer = .5f; RegisterReinforcements(); }
		TickPendingSpawns(dt);
		if (State == PhaseState.Surviving)
		{
			int index = 0;
			for (int i = 1; i < Definition!.Phases.Length; i++) if (ElapsedSeconds >= Definition.DurationSeconds * Definition.Phases[i].StartFraction) index = i;
			if (index != _phaseIndex) { _phaseIndex = index; Notice = $"新阶段 · {PhaseTitle}"; }
			if (ElapsedSeconds >= Definition.DurationSeconds)
			{
				CancelPendingSpawns(); State = PhaseState.FinalBoss; _spawnTimer = 0; Notice = "终局首领降临！击败后前往撤离门。";
				StopEliteTraits();
			}
			else
			{
				var phase = Definition.Phases[_phaseIndex];
				_bank = Mathf.Min(Mathf.Max(32, phase.MaxAlivePressure), _bank + phase.BudgetPerSecond * dt);
				_spawnTimer -= dt;
				if (_spawnTimer <= 0)
				{
					_spawnTimer = Definition.SpawnInterval;
					bool milestone = _milestoneIndex < Definition.MilestoneFractions.Length && ElapsedSeconds >= Definition.DurationSeconds * Definition.MilestoneFractions[_milestoneIndex];
					if (milestone) { if (TryQueueEnemy(Definition.MilestoneEnemy!, true, true)) _milestoneIndex++; }
					else TryQueueWeightedEnemy(phase);
				}
			}
		}
		if (State == PhaseState.FinalBoss && _boss == null && !_pending.Any(p => p.Boss))
		{
			_spawnTimer -= dt; if (_spawnTimer <= 0) { _spawnTimer = .5f; TryQueueBoss(); }
		}
		TryOpenReward();
	}
	public void GrantExperience(int value)
		=> GrantExperience(value, SurvivalExperienceSource.Enemy);
	public void GrantExperience(int value, SurvivalExperienceSource source)
	{
		if (!Active || State == PhaseState.Preparing || value <= 0 || _run?.RunEnded != false) return;
		double adjusted = value * (source == SurvivalExperienceSource.Enemy ? BuildRuntime?.ExperienceScale ?? 1 : 1) + _experienceRemainder;
		int granted = (int)Math.Floor(adjusted + .000001); _experienceRemainder = adjusted - granted;
		Experience += granted;
		while (Experience >= NextLevelExperience)
		{
			Experience -= NextLevelExperience; Level++;
			// 保留原强化/混合奖励节拍，旧专属轮次改用通用混合池，不减少升级奖励。
			_rewards.Enqueue((Level % 3 == 1 ? RewardKind.Enhancement : null, $"等级 {Level} · 选择增幅"));
		}
		ExperienceCollected?.Invoke(new SurvivalExperienceReceipt(value, granted, source));
	}
	private void TryOpenReward()
	{
		if (_choicePending || _rewards.Count == 0 || !Active || State == PhaseState.Preparing || _run == null) return;
		var ticket = _rewards.Peek(); RewardKind? filter = ticket.Kind;
		if (!_run.CanOfferModeReward(filter, false)) filter = null;
		if (!_run.CanOfferModeReward(filter, false))
		{
			_player!.Heal(_player.MaxHealth * .15f); _rewards.Dequeue(); Notice = "可用增幅已全部取得，本次成长转为恢复15%生命。"; return;
		}
		int generation = _generation;
		_choicePending = true;
		bool opened = _run.OfferModeReward(filter, ticket.Title, () =>
		{
			if (generation != _generation || !Active || _run.RunEnded) return;
			_choicePending = false; if (_rewards.Count > 0) _rewards.Dequeue();
			_traitWorld?.SuspendDamage(false);
		});
		if (!opened) _choicePending = false;
		else _traitWorld?.SuspendDamage(true);
	}
	public bool CompleteBeacon(SurvivalObjective objective)
	{
		if (State != PhaseState.Surviving || objective.Kind != SurvivalObjective.ObjectiveKind.Beacon || !_objectives.Contains(objective) || !_claimedObjectives.Add(objective)) return false;
		CompletedBeacons++; CompletedObjectives++;
		_player!.Heal(_player.MaxHealth * .15f);
		_rewards.Enqueue((null, "信标净化 · 选择增幅"));
		Notice = CompletedBeacons == 3 ? "三座信标已净化 · 终局首领生命降低" : $"信标已净化 {CompletedBeacons}/3 · 恢复生命并获得增幅";
		return true;
	}
	public bool ClaimRelic(SurvivalObjective objective)
	{
		if (!Active || State == PhaseState.Preparing || objective.Kind != SurvivalObjective.ObjectiveKind.Relic || !_objectives.Contains(objective) || !_claimedObjectives.Add(objective)) return false;
		_rewards.Enqueue((null, "强敌遗物 · 选择增幅")); return true;
	}
	public bool Extract() => State == PhaseState.AwaitingExit && _run?.CompleteMode(this, true) == true;
	public override StageStatistics CaptureStatistics() => _frozen ?? new StageStatistics(1, "survival_twilight", DisplayName, ElapsedSeconds, CompletedObjectives, BossDefeated);
	private void ReleasePlayer()
	{
		if (_heldPlayer && _player != null && IsInstanceValid(_player)) _player.ProcessMode = _playerProcessMode;
		_heldPlayer = false;
	}
	public override void Stop()
	{
		if (State is PhaseState.Dormant or PhaseState.Stopped) return;
		_frozen ??= CaptureStatistics(); State = PhaseState.Stopped; _generation++; _choicePending = false; _rewards.Clear(); ReleasePlayer();
		BuildRuntime?.Stop(); if (BuildRuntime != null && IsInstanceValid(BuildRuntime)) BuildRuntime.QueueFree();
		SceneRune?.Stop(); if (SceneRune != null && IsInstanceValid(SceneRune)) SceneRune.QueueFree(); SceneRune = null; SceneRuneChanged?.Invoke();
		StopEliteTraits();
		CancelPendingSpawns(); ClearEnemies();
		ClearShardPickups();
		if (_experience != null && IsInstanceValid(_experience)) { _experience.Collected -= GrantExperience; _experience.Clear(); _experience.QueueFree(); }
		foreach (var objective in _objectives) if (IsInstanceValid(objective)) objective.QueueFree(); _objectives.Clear();
		if (_hud != null && IsInstanceValid(_hud)) _hud.QueueFree();
	}
	public override void _ExitTree() => Stop();
}

