using System.Collections.Generic;
using Godot;

namespace ActRoguelike.Config;

[Tool, GlobalClass]
public partial class SurvivalDefinition : RunModeDefinition
{
	[Export] public float DurationSeconds { get; set; } = 720;
	[Export] public SceneRuneDefinition[] SceneRunePool { get; set; } = System.Array.Empty<SceneRuneDefinition>();
	[Export] public SceneRuneDefinition? FixedSceneRune { get; set; }
	[Export] public SurvivalPhase[] Phases { get; set; } = System.Array.Empty<SurvivalPhase>();
	[Export] public BossConfig? FinalBoss { get; set; }
	[Export] public EnemyConfig? MilestoneEnemy { get; set; }
	[Export] public float[] MilestoneFractions { get; set; } = new[] { .25f, .5f, .75f };
	[Export] public float SpawnMinDistance { get; set; } = 15;
	[Export] public float SpawnMaxDistance { get; set; } = 25;
	[Export] public float SpawnWarningSeconds { get; set; } = .75f;
	[Export] public float SpawnInterval { get; set; } = .45f;
	[Export] public float ExperiencePerPressure { get; set; } = 2;
	[Export] public int BaseLevelExperience { get; set; } = 14;
	[Export] public int LevelExperienceStep { get; set; } = 7;
	[Export] public int MaxExperienceMotes { get; set; } = 384;
	[Export] public float PickupRadius { get; set; } = 4;
	[Export] public int EliteKillShardDrop { get; set; } = 10;
	[Export] public int BossKillShardDrop { get; set; } = 50;
	[Export] public float ShardPickupRadius { get; set; } = 1.4f;
	[Export] public PackedScene? ShardPickupScene { get; set; }
	[Export] public float BeaconCaptureSeconds { get; set; } = 8;
	[Export] public float BeaconRadius { get; set; } = 5;
	[Export] public float BossHealthScale { get; set; } = .8f;
	[Export] public float CompletedBeaconsBossScale { get; set; } = .7f;
	[Export] public Vector3[] BeaconPositions { get; set; } = new[] { new Vector3(-25, 0, -22), new Vector3(25, 0, -17), new Vector3(0, 0, 28) };
	public int ExperienceForLevel(int level) => BaseLevelExperience + Mathf.Max(0, level - 1) * LevelExperienceStep;
	public override string DescribeForDeparture() => $"生存阶段约 {DurationSeconds / 60:0.#} 分钟 → 终局首领 → 互动撤离。\n击杀拾取经验，升级暂停三选一；保留当前武技、Q／E技能和手动瞄准。\n三处信标是可选目标：范围内守候 {BeaconCaptureSeconds:0.#} 秒取得收益，全部完成后削弱首领。\n增援有落点预告；暂停与奖励选择不推进计时。Esc可取消本局并回到出击前。";
	public override IEnumerable<string> Validate()
	{
		if (EliteKillShardDrop < 0 || BossKillShardDrop < 0 || !float.IsFinite(ShardPickupRadius) || ShardPickupRadius <= 0)
			yield return "碎片掉落不能为负，拾取范围必须为有限正数。";
		var sceneRuneIds = new HashSet<string>();
		foreach (var rune in SceneRunePool)
		{
			if (rune == null || !sceneRuneIds.Add(rune.Id)) { yield return "SceneRunePool：不能包含空项或重复场景符文。"; continue; }
			foreach (string error in rune.Validate()) yield return "SceneRunePool：" + error;
		}
		if (FixedSceneRune != null) foreach (string error in FixedSceneRune.Validate()) yield return "FixedSceneRune：" + error;
		if (string.IsNullOrWhiteSpace(Id)) yield return "Id：必须填写模式的稳定Id。";
		if (string.IsNullOrWhiteSpace(Title) || !float.IsFinite(DurationSeconds) || DurationSeconds <= 0) yield return "Title / DurationSeconds：名称不能为空，时长必须为有限正数。";
		if (Phases.Length == 0 || Phases[0] == null || Phases[0].StartFraction != 0) yield return "Phases：必须从0开始。";
		float previous = -1;
		foreach (var phase in Phases)
		{
			if (phase == null) { yield return "Phases：存在空阶段。"; continue; }
			if (phase.StartFraction <= previous) yield return "Phases：阶段必须严格递增。";
			previous = phase.StartFraction;
			foreach (var error in phase.Validate()) yield return error;
		}
		if (FinalBoss == null || !ResourceLoader.Exists(FinalBoss.ScenePath)) yield return "FinalBoss：必须指定有效首领。";
		if (MilestoneEnemy == null || MilestoneEnemy.IsGlobal || !ResourceLoader.Exists(MilestoneEnemy.ScenePath)) yield return "MilestoneEnemy：必须指定有效强化敌人。";
		previous = 0;
		foreach (float time in MilestoneFractions)
		{
			if (!float.IsFinite(time) || time <= previous || time >= 1) yield return "MilestoneFractions：时间点必须在(0,1)且严格递增。";
			previous = time;
		}
		foreach (var position in BeaconPositions) if (!position.IsFinite()) yield return "BeaconPositions：信标坐标必须为有限值。";
		foreach (float value in new[] { SpawnMinDistance, SpawnMaxDistance, SpawnWarningSeconds, SpawnInterval, ExperiencePerPressure, PickupRadius, BeaconCaptureSeconds, BeaconRadius, BossHealthScale, CompletedBeaconsBossScale }) if (!float.IsFinite(value) || value <= 0) yield return "生存参数必须为有限正数。";
		if (SpawnMaxDistance < SpawnMinDistance || BaseLevelExperience < 1 || LevelExperienceStep < 0 || MaxExperienceMotes < 1 || BeaconPositions.Length != 3) yield return "生成距离、经验门槛、拾取物上限或三处信标配置无效。";
	}
}

Scripts/Rewards/RunController.cs.text:
using System;
using ActRoguelike.Core;
using System.Collections.Generic;
using ActRoguelike.Abilities;
using ActRoguelike.AbilityCards;
using ActRoguelike.Combat;
using ActRoguelike.Config;
using ActRoguelike.Encounter;
using ActRoguelike.Interaction;
using ActRoguelike.Run;
using ActRoguelike.UI;
using ActRoguelike.Weapons;
using Godot;

namespace ActRoguelike.Rewards;

/// <summary>
/// 本局控制器：持有构筑与奖励池，驱动 Stage/Node 流程，并处理胜负结算。
/// </summary>
public partial class RunController : Node
{
	[Export] public bool AutoStartStage { get; set; } = true;
	[Export] public NodePath ModeControllerPath { get; set; } = "";
	private RunModeController? _mode;
	public RunModeController? Mode => _mode;
	public bool GameplayReady => _boot == 2 && !_runEnded;

	private readonly RunBuild _build = new();
	private readonly RewardPool _pool = new();
	private readonly RewardOfferFlow _rewardFlow = new();
	private Action? _refreshRewardOffer;
	private NodeRewardContext? _nodeRewardContext;

	private readonly ActRoguelike.Player.PlayerLoadout _loadout = new();

	private Unit? _player;
	private Weapon? _weapon;
	private RewardScreen? _screen;
	private StageController? _stage;
	private bool _poolReady;
	private bool _runEnded;
	private bool _awaitingAdvance;
	private StageDefinition[] _stages = Array.Empty<StageDefinition>();
	private int _stageIndex;
	private bool _restartOnDismiss;
	private WeaponPresetKind _weaponKind = WeaponPresetKind.EnergyPalm;
	private ChooseScreen? _chooseScreen;
	private PlayerCharacterKind _character = PlayerCharacterKind.Hunter;
	private int _boot;
	private readonly List<StageStatistics> _stageStatistics = new();
	private float _recordedSeconds;
	private int _recordedChallenges;
	private int _recordedStageNumber;

	// ── J11：符文（开局携带一件的信物）────────────────────────────────────────────
	/// <summary>当前携带的符文行 Id（空 = 不携带，默认）。来源：`RuneCarry`（`user://rune.cfg`）。</summary>
	private string _carriedRuneId = string.Empty;

	/// <summary>
	/// 符文效果的修正器**专用 Source**（一个 `RunBuild` 实例）。用独立实例而不是 `_build` 的原因：
	/// 换符文 / 重新开局时要能 `Stats.RemoveBySource(它)` 一次摘干净，而不碰 `_build` 挂的增幅修正器
	/// （`_build` 的修正器由 `PlayerLoadout.Apply` 里的 `RemoveBySource(owner)` 管，两者互不干扰）。
	/// </summary>
	private readonly RunBuild _runeBuild = new();

	/// <summary>这枚符文建出来的规则节点（击杀加甲 / 死亡避免 / 小精灵…）—— 换符文时按清单摘掉。</summary>


	public RunBuild Build => _build;
	/// <summary>当前装备的只读身份，供HUD按表筛选技能；不暴露可变的配装状态。</summary>
	public PlayerCharacterKind CurrentCharacter => _character;
	public WeaponPresetKind CurrentWeapon => _weaponKind;
	public int CandidateCount => _pool.CandidateCount;
	public bool RunEnded => _runEnded;
	public bool CanCancelAdventure => !_runEnded && _boot == 2 && AdventureCheckpoint.IsActive;
	public bool CancelAdventure(out string error)
	{
		error = string.Empty;
		if (!CanCancelAdventure) { error = "当前没有进行中的冒险。"; return false; }
		PackedScene home = RuntimeResources.Load<PackedScene>("res://Scenes/Levels/Base.tscn");
		if (home == null || !home.CanInstantiate()) { error = "基地尚未加载成功，请稍后重试。"; return false; }
		if (!AdventureCheckpoint.TryRestore(out error)) return false;
		_runEnded = true; _restartOnDismiss = false; _awaitingAdvance = false; _rewardFlow.Cancel(); _nodeRewardContext?.Cancel(); _refreshRewardOffer = null;
		_mode?.Stop();
		_screen?.Close();
		UiRouter.Instance?.ResetForSceneChange();
		GameLog.Write("Flow", "取消本次冒险：已恢复出击前的资源、配装和基地状态，不进行本局结算。");
		Error result = GetTree().ChangeSceneToPacked(home);
		if (result != Error.Ok) { error = "返回基地失败，请重新载入基地。"; return false; }
		return true;
	}
	/// <summary>已完结关卡的快照；换关前收集，死亡时也收集当前关，关卡序号只入账一次。</summary>
	public IReadOnlyList<StageStatistics> StageStatistics => _stageStatistics.AsReadOnly();
	public float TotalElapsedSeconds => _recordedSeconds + (_mode != null && _recordedStageNumber == 0 ? _mode.CaptureStatistics().ElapsedSeconds : _stage != null && _stage.StageNumber != _recordedStageNumber ? _stage.ElapsedSeconds : 0f);
	public int TotalChallengesStarted => _recordedChallenges + (_mode != null && _recordedStageNumber == 0 ? _mode.CaptureStatistics().ChallengesStarted : _stage != null && _stage.StageNumber != _recordedStageNumber ? _stage.ChallengesUsed : 0);
	public int SettlementEarnedShards { get; private set; }

	/// <summary>当前携带的符文行 Id（空 = 不携带；J11 第 ⑤ 步的运行期字段）。</summary>
	public string CarriedRuneId => _carriedRuneId;

	/// <summary>当前携带的符文行（读不到 = null）。</summary>
	public RuneConfig? CarriedRune => ConfigRows.ById<RuneConfig>(_carriedRuneId);

	/// <summary>本局控制器单例（地面节点通过它领奖励）。</summary>
	public static RunController? Instance { get; private set; }

	public override void _Ready()
	{
		Instance = this;
		if (!ModeControllerPath.IsEmpty) _mode = GetNodeOrNull<RunModeController>(ModeControllerPath);
		AddToGroup("run_controller");
		_screen = UiService.Instance?.Screen<RewardScreen>();
		if (_screen != null)
		{
			_screen.RewardChosen += OnRewardChosen;
			_screen.MessageDismissed += OnMessageDismissed;
		}

		// 兄弟节点的 _Ready 顺序不定（RunController 早于 Stage），这里只尝试一次，失败就在首帧惰性绑定。
		BindStage();
	}

	private void BindStage()
	{
		if (_mode != null) return;
		_stage = GetTree().GetFirstNodeInGroup("stage") as StageController;
		if (_stage == null)
		{
			return;
		}

		_stage.NodeCleared += OnNodeCleared;
		_stage.Victory += OnVictory;
	}

	/// <summary>把 ConfigIndex.tres 的数值套到玩家、武器与节点节奏上（开局与换角色时调用）。</summary>
	private void ApplyBalance()
	{
		ConfigIndexData config = ConfigIndex.Settings;
		if (CharacterRow(_character) is { } selected && !LoadoutSelection.Allows(selected, WeaponRow(_weaponKind))
			&& LoadoutSelection.FirstWeapon(selected) is { } fallback)
		{
			_weaponKind = (WeaponPresetKind)(fallback.Slot - 1);
		}

		_loadout.Apply(_player!, this, _character, _weaponKind);

		// ⭐ J11 第 ⑤ 步：**开局把携带的符文应用到玩家**（顺手把"上一枚符文"的残留摘掉）。
		// 位置在 `_loadout.Apply` 之后：那时角色/武器的数值已经套好、生命也回满了，
		// 「雷之印」的 30 上限才是在 220 之上夹下来的（顺序反了会被后面的回满覆盖）。
		ApplyCarriedRune();

		// 奖励候选池：**进关卡初始化时**就按"当前角色 + 当前武器"把池内容定下来（用户 2026-10-12 C2：
		// 「进化池里会出什么选项是根据交互的角色持有的攻击方式（武器）……池里一开始有什么，
		// 应该在进入关卡初始化的时候就判断好的」）。放在这里而不是第一次交互时 ——
		// ApplyBalance 正是"角色/武器都定了、进关卡"的那一刻（BeginRunWithCharacter → ApplyStage(0)）。
		InitializePool();

		if (_stage == null)
		{
			return;
		}

		foreach (Node child in _stage.GetChildren())
		{
			if (child is not EncounterController node)
			{
				continue;
			}

			node.TotalBudget *= config.NodeBudgetMultiplier;
			node.SpawnInterval *= config.SpawnIntervalMultiplier;
		}
	}

	public override void _ExitTree()
	{
		if (_mode != null && IsInstanceValid(_mode)) _mode.Stop();
		_rewardFlow.Cancel(); _nodeRewardContext?.Cancel(); _refreshRewardOffer = null;
		if (Instance == this)
		{
			Instance = null;
		}

		if (_screen != null)
		{
			_screen.RewardChosen -= OnRewardChosen;
			_screen.MessageDismissed -= OnMessageDismissed;
		}

		if (_stage != null)
		{
			_stage.NodeCleared -= OnNodeCleared;
			_stage.Victory -= OnVictory;
		}
	}

	public override void _Process(double delta)
	{
		_build.TickTriggers((float)delta);

		if (_stage == null)
		{
			BindStage();
		}

		if (_player == null || !IsInstanceValid(_player))
		{
			ResolvePlayer();
		}

		// 开局引导：等玩家、武器、Stage 都就绪 → 套用平衡配置 → 应用第一关配置。
		if (_boot == 0 && _player != null && _weapon != null && (_stage != null || _mode != null))
		{
			_boot = 1;
			// J11：**先**读"当前携带的符文"（`user://rune.cfg`），再套配置 —— 这样第一次 `ApplyBalance`
			// 就已经带着符文了。读不到 = 不携带，与加符文之前逐位一致。
			_carriedRuneId = RuneCarry.Current;
			ApplyBalance();
			_stages = _mode == null ? ResolveStages() : Array.Empty<StageDefinition>();
			MetaProgress.Load();

			// ⚠️ **命令行旁路必须判在「基地已经选过一局」之前**（`docs/anim-pipeline.md` §6.4-2）：
			// `RunSetup.HasSelection` 是**静态**的，基地里选过一局之后就一直是 true，
			// 而它下面那条分支会 `return`，于是 `BeginConfigure`（只有它读命令行）永远轮不到 ——
			// `--char/--weapon` 就"静默失效"了。放在这里，两边都成立：
			//   ① 给了参数 → 直接按参数开局（跳过基地/选人界面）；
			//   ② 没给参数 → 完全走原来的流程（基地已配置过就直接开局，否则开基地界面）。
			if (TryApplyLoadoutOverride())
			{
				_boot = 2;
				return;
			}

			// 主循环起点：**基地场景**（`Scenes/Levels/Base.tscn`）→ 出击门（`BaseTerminal` 的
			// `Kind = Gate`，走到跟前按 F）→ 本场景。出击门已经先把角色/武器写进 `RunSetup` 再切场景，
			// 所以到这里"只是切场景"：直接按那份配置开局。
			// ⚠️ P6a **删掉了「开始探索」按钮与它后面那道关卡内选人/选武器界面** —— 用户 2026-10-15：
			// 「那个本身按了没意义……后来要求的进关卡就是去交互一个对象来进关卡，基地里是有做了一个的」。
			// 没走基地就直接跑 `Main.tscn`（MCP / 命令行调试）时，`RunSetup` 的默认值
			// （角色 A［猎手］+ 能量掌）就是这一局的配置，这条路一样成立。
			ActRoguelike.Core.GameLog.Write(
				"Flow",
				$"开局配置：角色 {RunSetup.Character} / 武器 {RunSetup.Weapon}（基地里选过={RunSetup.HasSelection}）—— 进关卡只是切场景，直接开局");
			BeginRunWithCharacter(RunSetup.Character, RunSetup.Weapon);
			_boot = 2;
		}

		if (_player is { IsDead: true } && !_runEnded)
		{
			EndRun(false);
		}
	}

	/// <summary>战斗清场：现在只是回到自由探索，不再自动发奖励（策划文档 §6.2 的流程由地面节点驱动）。</summary>
	private void OnNodeCleared(int index, EncounterController node)
	{
	}

	private void OnVictory()
	{
		if (_runEnded)
		{
			return;
		}
		RecordCurrentStage();
		// 打完一关的 Boss：还有下一关就推进，否则通关。
		int cleared = _stageIndex;
		if (_stageIndex + 1 < _stages.Length)
		{
			ApplyStage(_stageIndex + 1);
			_restartOnDismiss = false;
			_screen?.OpenMessage(
				$"{_stages[cleared].DisplayName} 完成",
				$"第 {cleared + 1} 关结束，构筑保留，生命回满。\n{_build.Describe()}\n\n进入 {_stages[_stageIndex].DisplayName}",
				"按 Enter 或点击继续");
			return;
		}

		EndRun(true);
	}

	/// <summary>应用第 index 关（切关时玩家回出生点、回满，关卡状态由 Stage 自己重置）。</summary>
	private void ApplyStage(int index)
	{
		_stageIndex = index;
		ActRoguelike.Core.GameLog.Write("Flow", $"进入第 {index + 1} 关：{_stages[index].DisplayName}");
		_stage?.ApplyStage(_stages[index], index + 1, index == _stages.Length - 1);

		if (_player != null && IsInstanceValid(_player))
		{
			_player.GlobalPosition = GetTree().GetFirstNodeInGroup("run_spawn") is Node3D spawn
				? spawn.GlobalPosition : new Vector3(0f, 0.8f, 0f);
			_player.FillVitals();
		}
	}

	/// <summary>
	/// 调试用的"直接开局"：命令行 <c>--char=&lt;角色行 Id&gt; --weapon=&lt;武器行 Id&gt;</c>
	/// （也可以传枚举名，例如 <c>--char=Hunter</c>）。
	///
	/// **按表行 Id 选**（不是按索引）—— 这正是"加角色/武器不改代码"该有的样子。
	/// 一个参数都没给就返回 false，走正常流程（基地里选好的那份配置，或默认值）。
	///
	/// <para>⚠️ P6a：关卡内那道 <c>BeginConfigure</c> 选人界面已随「开始探索」按钮一起删除
	/// （用户 2026-10-15：「后来要求的进关卡就是去交互一个对象来进关卡」）。这条命令行旁路保留 ——
	/// 它只改"这一局用哪个角色/武器"，与界面无关。</para>
	/// </summary>
	private bool TryApplyLoadoutOverride()
	{
		string? charArg = null;
		string? weaponArg = null;
		foreach (string arg in OS.GetCmdlineUserArgs())
		{
			if (arg.StartsWith("--char=", StringComparison.Ordinal))
			{
				charArg = arg.Substring("--char=".Length);
			}
			else if (arg.StartsWith("--weapon=", StringComparison.Ordinal))
			{
				weaponArg = arg.Substring("--weapon=".Length);
			}
		}

		if (string.IsNullOrEmpty(charArg) && string.IsNullOrEmpty(weaponArg))
		{
			return false;
		}

		PlayerCharacterKind character = _character;
		WeaponPresetKind weapon = _weaponKind;

		if (!string.IsNullOrEmpty(charArg) && !TryResolveCharacter(charArg, out character))
		{
			GD.PushWarning($"[RunController] --char={charArg} 在角色表里找不到（也没有同名枚举），忽略。");
		}

		if (!string.IsNullOrEmpty(weaponArg) && !TryResolveWeapon(weaponArg, out weapon))
		{
			GD.PushWarning($"[RunController] --weapon={weaponArg} 在武器表里找不到（也没有同名枚举），忽略。");
		}

		ActRoguelike.Core.GameLog.Write("Flow", $"命令行指定开局：角色 {charArg ?? "（默认）"} → {character} / 武器 {weaponArg ?? "（默认）"} → {weapon}");
		RunSetup.HasSelection = true;
		RunSetup.Character = character;
		RunSetup.Weapon = weapon;
		BeginRunWithCharacter(character, weapon);
		return true;
	}

	/// <summary>按角色表行 Id（或枚举名）解析角色。表是权威 —— 加一行角色就能直接 --char 用。</summary>
	public static bool TryResolveCharacter(string idOrName, out PlayerCharacterKind kind)
	{
		foreach (CharacterConfig row in ConfigIndex.Settings.Characters)
		{
			if (row != null && string.Equals(row.Id, idOrName, StringComparison.OrdinalIgnoreCase))
			{
				kind = (PlayerCharacterKind)(row.Slot - 1);
				return true;
			}
		}

		return Enum.TryParse(idOrName, true, out kind);
	}

	/// <summary>按武器表行 Id（或枚举名）解析武器。</summary>
	public static bool TryResolveWeapon(string idOrName, out WeaponPresetKind kind)
	{
		foreach (WeaponConfig row in ConfigIndex.Settings.Weapons)
		{
			if (row != null && string.Equals(row.Id, idOrName, StringComparison.OrdinalIgnoreCase))
			{
				kind = (WeaponPresetKind)(row.Slot - 1);
				return true;
			}
		}

		return Enum.TryParse(idOrName, true, out kind);
	}

	/// <summary>
	/// 关卡序列的来源（设计文档 config-schema.md §4.2 / §5 阶段 1）：
	/// **只有一个真源** —— <see cref="ActRoguelike.Config.ConfigIndexData.Stages"/>（`Config/ConfigIndex.tres`
	/// 上的数组，元素指向 `Config/Tables/Stages/stg_*.tres`）。
	/// 读不到 / 空表 → 回退到 <see cref="StageDefinition"/> 自身的 `[Export]` 默认值，
	/// **不再有第二份兜底表**（原来的 `DefaultStages()` 与 `ConfigIndex.tres` 已经漂移了 5 处，
	/// 最严重的是 Stage2 的 AllowedEnemies 走兜底会变成"不限制"）。
	/// ⚠️ 实测：删/改一个被引用的行文件 → Godot 会**整份** `ConfigIndex.tres` 加载失败，
	/// 所以走的是"0 关 → 单关默认值"这条粗回退（其他数值也一起回退）。别再删行文件，见 docs/config-schema.md §5。
	/// 回退留痕：日志里能直接看到这一局走的是"表"还是"默认值"。
	/// </summary>
	private static StageDefinition[] ResolveStages()
	{
		StageDefinition[] table = ActRoguelike.Config.ConfigIndex.Settings.Stages;
		if (table is not { Length: > 0 })
		{
			// 连"整张表"都读不到时，把全局数值的来源也打出来：这样一眼能区分
			// 「只是关卡表为空」和「连 ConfigIndex.tres 都没加载上（所有数值都回退了）」。
			string source = ActRoguelike.Config.ConfigIndex.Instance?.FileLoaded == true ? "ConfigIndex.tres 已加载" : "ConfigIndex.tres 未加载（全部数值回退到代码默认值）";
			ActRoguelike.Core.GameLog.Write("Flow", $"关卡表：0 关（来源：默认值）—— ConfigIndex 的 Stages 为空或未找到，使用 StageDefinition 自身的默认值。（{source}）");
			GD.PushWarning("[Config] 关卡表为空，使用 StageDefinition 自身默认值。");
			return new[] { new StageDefinition() };
		}

		var stages = new List<StageDefinition>(table.Length);
		int missing = 0;
		foreach (StageDefinition? row in table)
		{
			// ⚠️ 实测（2026-10）：行文件被删/改名时，**在游戏里根本走不到这里** —— 缺依赖会让
			// `GD.Load<ConfigIndexData>` 整份失败（于是走上面"0 关"那条分支，所有数值一起回退到代码默认值，
			// 实测玩家生命 250→160）。这个空档分支只在"数组里真的出现空元素"时兜底，纯粹是防 NullReference。
			if (row == null)
			{
				missing++;
				stages.Add(new StageDefinition());
				continue;
			}

			stages.Add(row);
		}

		var summary = new System.Text.StringBuilder();
		foreach (StageDefinition row in stages)
		{
			summary.Append($" | {row.Id} {row.DisplayName} 允许敌人[{row.AllowedEnemyIds.Length}] 敌伤×{row.EnemyDamageMultiplier:0.##} Boss伤×{row.BossDamageMultiplier:0.##} Boss词条{row.BossPerkCount}");
		}

		ActRoguelike.Core.GameLog.Write("Flow", $"关卡表：{stages.Count} 关（来源：表{(missing > 0 ? $"，缺 {missing} 行→该关用默认值" : string.Empty)}）{summary}");
		if (missing > 0)
		{
			GD.PushWarning($"[Config] 关卡表有 {missing} 行读不到（文件被删/改名？），这些关使用 StageDefinition 自身默认值。");
		}

		return stages.ToArray();
	}

	/// <summary>在 Stage 重置之前入账；防止首领通知与最终结算重复收集同一关。</summary>
	private void RecordCurrentStage()
	{
		if (_mode != null)
		{
			if (_recordedStageNumber != 0) return;
			var captured = _mode.CaptureStatistics();
			_stageStatistics.Add(captured); _recordedStageNumber = captured.StageNumber;
			_recordedSeconds += captured.ElapsedSeconds; _recordedChallenges += captured.ChallengesStarted;
			return;
		}
		if (_stage == null || _stage.Definition == null || _recordedStageNumber == _stage.StageNumber)
		{
			return;
		}
		StageStatistics statistics = _stage.CompleteStatistics();
		_stageStatistics.Add(statistics);
		_recordedStageNumber = statistics.StageNumber;
		_recordedSeconds += statistics.ElapsedSeconds;
		_recordedChallenges += statistics.ChallengesStarted;
	}

	private void EndRun(bool victory)
	{
		if (_runEnded)
		{
			return;
		}

		_runEnded = true;
		_rewardFlow.Cancel(); _nodeRewardContext?.Cancel(); _refreshRewardOffer = null;
		RecordCurrentStage();
		ActRoguelike.Core.GameLog.Write("Flow", $"本局结束 victory={victory} 关卡={_stage?.Definition?.DisplayName} 本局用时={TotalElapsedSeconds:0}s 本局挑战={TotalChallengesStarted}");
		_mode?.Stop();
		_restartOnDismiss = true;
		int earned = _mode?.SettlementShards(victory) ?? RunSettlement.ShardsFor(_stageIndex, TotalChallengesStarted, victory);
		SettlementEarnedShards = earned;
		MetaProgress.AddShards(earned);
		AdventureCheckpoint.Complete();
		string body = _mode?.DescribeSettlement(victory, _build.Describe(), earned, MetaProgress.Shards) ?? RunSettlement.Describe(victory, _stage?.Definition?.DisplayName ?? "关卡", _build.Describe(),
			earned, MetaProgress.Shards, TotalElapsedSeconds, TotalChallengesStarted, _stages.Length);

		// 阵亡 → **死亡流程**（用户需求 §五 #3）：死亡动画 → 演示过渡面板（占位）→ 回基地。
		// 这一段**替代**原来的"立刻弹结算消息、按 Enter 回基地"，所以要在 OpenMessage 之前返回；
		// 场景里没有 DeathScreen 时（老场景 / 单独跑某个测试场景）自动落回原来的消息路径，不会卡住。
		// ⚠️ 顺带修掉一个既有 bug：原来连着调了两次 `OpenMessage`（第二次想补上碎片那行），
		// 而 `UiService.OpenMessage` 要求 `IsOpen == false` —— 第二次必然被拒，所以"获得碎片 +N"从来没显示过。
		if (!victory && GetTree().CurrentScene?.GetNodeOrNull<DeathScreen>("DeathScreen") is { } death)
		{
			// 回基地由 DeathScreen 自己切场景，不再需要"按 Enter 重开"那条路。
			_restartOnDismiss = false;
			death.BeginDeath("本局结束", body);
			return;
		}

		_screen?.OpenMessage(victory ? "胜利" : "本局结束", body, "按 Enter 或点击返回基地");
	}

	private void OnMessageDismissed()
	{
		_screen?.Close();

		// 只有结算（胜利/失败）才重开一局；关卡之间的提示是继续本局。
		if (!_restartOnDismiss)
		{
			return;
		}

		GetTree().Paused = false;
		// 结算后回基地场景（主场景是基地：出征 → 关卡 → 回基地）。
		RunSetup.Clear();
		ActRoguelike.Core.GameLog.Write("Flow", "本局结束 → 返回基地场景");
		RuntimeResources.ChangeScene(GetTree(), "res://Scenes/Levels/Base.tscn");
	}

	/// <summary>直接发放指定奖励（保底奖励、脚本奖励与自动化验证用）。</summary>
	public bool GrantReward(string id)
	{
		if (_player == null || !IsInstanceValid(_player))
		{
			ResolvePlayer();
		}

		RewardDefinition? definition = RewardCatalog.Find(id);
		if (definition == null || !definition.AllowsMode(_mode?.ModeId ?? string.Empty) || _player == null || _weapon == null)
		{
			return false;
		}

		_build.Add(definition, new RewardContext { Player = _player, Weapon = _weapon, Build = _build });
		return true;
	}

	/// <summary>当前真正可获取的增幅；GM浏览与正式抽取使用同一限定、前置和互斥规则。</summary>
	public List<RewardDefinition> AvailableRewards(RewardKind? kind = null)
	{
		if (_runEnded || _player == null || !IsInstanceValid(_player) || _player.IsDead || _weapon == null) return new();
		EnsurePool();
		return _pool.Available(_build, kind);
	}

	/// <summary>GM列表点击获取：点击时重新核对资格，再走真实应用路径。</summary>
	public bool TryAcquireReward(string id)
	{
		RewardDefinition? definition = AvailableRewards().Find(row => row.Id == id);
		if (definition == null || _player == null || _weapon == null) return false;
		_build.Add(definition, new RewardContext { Player = _player, Weapon = _weapon, Build = _build });
		GameLog.Write("Reward", $"GM获取增幅 {definition.Name}（当前 {_build.StacksOf(id)} 层）");
		return true;
	}

	/// <summary>换装：三把武器共用一个 Weapon 节点，只换数值（数值权威在 `Config/Tables/Weapons/wpn_*.tres`）。
	/// 这样不用重建节点，也就不会把挂在武器下的输入组件一起弄丢。</summary>
	public void EquipWeapon(WeaponPresetKind kind)
	{
		_weaponKind = kind;
		if (_weapon == null || !IsInstanceValid(_weapon))
		{
			return;
		}

		WeaponConfig? row = WeaponRow(kind);
		if (row != null)
		{
			// 表是权威：一行 `.tres` 描述整把武器（含击退、暴击、弹速）。读不到行时才走下面的回退。
			row.ApplyTo(_weapon);
			return;
		}

		// 回退（表为空 / 整份 ConfigIndex.tres 未加载）：保留"什么都没做"的语义 ——
		// 武器组件自己的 [Export] 默认值就是这一把枪的数值。
		GD.PushWarning($"[Config] 武器表里没有 {kind}（Slot {(int)kind + 1}）的行，保留武器组件自身的默认值。");
	}

	/// <summary>按 <see cref="WeaponPresetKind"/> 取武器表的行（Slot 从 1 开始，与枚举顺序一致）。</summary>
	public static WeaponConfig? WeaponRow(WeaponPresetKind kind)
		=> ConfigRows.BySlot<WeaponConfig>((int)kind + 1);

	/// <summary>按 <see cref="PlayerCharacterKind"/> 取角色表的行（Slot 从 1 开始，与枚举顺序一致）。</summary>
	public static CharacterConfig? CharacterRow(PlayerCharacterKind kind)
		=> ConfigRows.BySlot<CharacterConfig>((int)kind + 1);

	/// <summary>
	/// 角色选择界面的卡片文案（标题 + 数值**全部来自角色表**：`DisplayName` + `DescriptionTemplate`，
	/// 后者支持 <c>{字段名}</c> 占位符）。
	///
	/// <para>⚠️ P6a **删掉了旧的 <c>DefaultCharacterTitle</c> 那张"角色枚举 → 手写中文标题"的映射表**
	/// —— 那正是"代码里写死角色名"（用户 §1.5 的硬要求）。现在加一个角色 = 加一行 `.tres`，
	/// 标题跟 `DisplayName` 走，C# 一行不动。</para>
	///
	/// <para>**public**：基地的装备配置台（<c>BaseTerminal</c>）复用它，角色卡的文案就只有这一处来源。</para>
	/// </summary>
	public static string CharacterCardText(PlayerCharacterKind kind)
	{
		CharacterConfig? row = CharacterRow(kind);
		if (row == null)
		{
			// 整张角色表都读不到：连名字都编不出来（这时玩家用的是场景里的原始数值）。
			return "（角色表读不到）";
		}

		string title = string.IsNullOrEmpty(row.DisplayName) ? row.Id : row.DisplayName;
		string detail = ConfigText.Format(
			string.IsNullOrEmpty(row.DescriptionTemplate)
				? "（{MaxHealth:0} 生命 / {StartingArmor:0} 护甲 / 减伤 {DamageReduction}）"
				: row.DescriptionTemplate,
			row,
			row.Params);
		return $"{title}（{detail}）";
	}


	/// <summary>选好角色与武器 → 套用数值并进入第一关。</summary>
	public void BeginRunWithCharacter(PlayerCharacterKind character, WeaponPresetKind kind)
	{
		AdventureCheckpoint.EnsureCaptured();
		_runEnded = false;
		_rewardFlow.Cancel(); _nodeRewardContext?.Cancel(); _refreshRewardOffer = null;
		_stageStatistics.Clear();
		_recordedSeconds = 0f;
		_recordedChallenges = 0;
		_recordedStageNumber = 0;
		SettlementEarnedShards = 0;
		_restartOnDismiss = false;
		_character = character;
		ActRoguelike.Core.GameLog.Write("Flow", $"选择角色 {character} / 武器 {kind}");
		_weaponKind = kind;
		ApplyBalance();

		if (_mode != null) { _mode.Begin(this, _player!); return; }
		if (_stages.Length == 0)
		{
			_stages = ResolveStages();
		}

		ApplyStage(0);
	}

	/// <summary>
	/// **按当前角色与武器把奖励候选池定下来**（池里有什么 = 交互的角色 × 攻击方式，用户 C2）。
	///
	/// 调用点只有一处：<see cref="ApplyBalance"/>（= 进关卡初始化）。在此之前池是"每次交互时惰性建"的
	/// 四个分支 —— 谁先被交互（例如先撞上特殊奖励节点）就会拿到不同的池。
	/// 现在初始化只有这一条路，角色/武器限定层一起定，交互时只从定好的池里抽。
	/// </summary>
	private void InitializePool()
	{
		if (_weapon == null)
		{
			return;
		}

		// ① 限定（角色层）：**当前角色的表行 Id**（`chr_hunter` …）。`<A限定>` 就是不填 Pool、只填这一列；
		//    `<A1限定>` = 这一列 + 选项行 Pool 指向该武器行的 Pool（资源引用，见 RewardConfig.RequiredCharacterIds）。
		string characterId = CharacterRow(_character)?.Id ?? string.Empty;
		// ② 限定（武器层）：专属池（ApplicablePoolIds）→ 武器标签（RequiredWeaponTags）→ 通用。
		_pool.Initialize(_weapon, characterId, _mode?.ModeId ?? string.Empty);
		_poolReady = true;

		// 留痕（用户 C2 问的就是"池是什么时候定的"）：这一行只在进关卡初始化时出现，
		// 之后每次交互只从这份池里抽（抽取时仍然要按当前构筑过滤互斥/前置/层数/节点类型）。
		string poolId = string.IsNullOrEmpty(_weapon.PoolId) ? "留空（走标签匹配 → 通用）" : _weapon.PoolId;
		ActRoguelike.Core.GameLog.Write(
			"Reward",
			$"奖励池按当前角色/武器定下来了（进关卡初始化）：角色 {_character}（行 Id「{(characterId.Length == 0 ? "（角色表读不到）" : characterId)}」）· 武器 {_weaponKind}（PoolId {poolId}）→ 候选 {_pool.CandidateCount} 条（限定两层之后）");
	}

	/// <summary>兜底：池子还没定就先定一次（正常路径一定在进关卡时已经定过）。</summary>
	private void EnsurePool()
	{
		if (!_poolReady)
		{
			InitializePool();
		}
	}

	/// <summary>
	/// ⭐ **J11 第 ⑤ 步：设置"当前携带的符文"**（本批唯一的写入口，C# / 自测可驱动）。
	///
	/// <para>做三件事：① 记进本局字段并**落盘**（`user://rune.cfg`，`RuneCarry`）；
	/// ② 如果本局已经在跑（玩家已就位），**立刻**摘掉旧符文的残留并套上新符文；
	/// ③ 写一行日志留痕（符文 Id / 读不到行时的警告 / 解锁了哪些前置）。</para>
	///
	/// <para>⚠️ **本批不做符文选择 UI**（用户划定范围）—— 下一批的基地选择台直接调这个方法即可，
	/// 不需要再碰任何判定代码。空 Id = 摘下符文，回到"没带符文"的逐位不变状态。</para>
	/// </summary>
	/// <returns>真正生效的符文行；口令为空或读不到那一行时返回 null（此时玩家身上没有符文效果）。</returns>
	public RuneConfig? SetCarriedRune(string? runeId)
	{
		_carriedRuneId = runeId ?? string.Empty;
		RuneCarry.Set(_carriedRuneId);

		if (_player == null || !IsInstanceValid(_player))
		{
			GameLog.Write(
				"Rune",
				$"携带符文设为「{(_carriedRuneId.Length == 0 ? "（无）" : _carriedRuneId)}」（本局还没开局，进关卡时再套到玩家身上）");
			return CarriedRune;
		}

		ApplyCarriedRune();
		return CarriedRune;
	}

	/// <summary>
	/// 把 <see cref="_carriedRuneId"/> 指向的那枚符文**应用到当前玩家**，并刷新它解锁的前置条件。
	///
	/// <para>两条通路缺一不可：</para>
	/// <list type="number">
	/// <item><b>效果</b>：走**既有的**处理器注册表（`RewardEffectRegistry.Compile` → `RewardDefinition.Apply`），
	///   与增幅项完全同一条路 —— 所以"符文"不需要第二套效果系统，
	///   `StatSet` / `GrantArmor` / `RuneEffect` 三类处理器都直接可用；</item>
	/// <item><b>前置解锁</b>：把符文行 Id + `UnlocksRequires` 里的派系名写进
	///   `RunBuild.SetRuneUnlocks`（读取点是 `RewardPool.HasPrerequisites`）。</item>
	/// </list>
	///
	/// <para>不携带任何符文时：修正器与节点清单都被清空、解锁名单为空 →
	/// **前置判定退化成改动前的 `StacksOf(id) > 0`**，玩家身上也没有任何符文修正器（逐位不变）。</para>
	/// </summary>
	private void ApplyCarriedRune()
	{
		if (_player == null || !IsInstanceValid(_player))
		{
			return;
		}

		// ① 先摘掉上一枚符文留下的一切（修正器按 Source 摘、规则节点按清单摘、前置名单清空）。
		_player.GetNodeOrNull<RewardEffectHost>(RewardEffectHost.NodeName)?.ReleaseBuild(_runeBuild);
		_player.Stats.RemoveBySource(_runeBuild);
		_build.SetRuneUnlocks(null);

		RuneConfig? row = ConfigRows.ById<RuneConfig>(_carriedRuneId);
		if (row == null)
		{
			_player.RefreshStats();
			GameLog.Write(
				"Rune",
				$"符文：不携带（CarriedRuneId「{_carriedRuneId}」{(string.IsNullOrEmpty(_carriedRuneId) ? "，默认" : " 在符文表里读不到")}）"
				+ " —— 前置判定只有「已拥有」一个来源，与加符文之前逐位一致；玩家没有任何符文修正器。");
			return;
		}

		if (_weapon == null || !IsInstanceValid(_weapon))
		{
			GD.PushWarning($"[Rune] 符文 {row.Id} 要套到玩家身上，但这一局还没有武器组件 —— 已跳过（下次 ApplyBalance 会重试）。");
			return;
		}

		// ② 前置解锁名单：符文行 Id（表里按 Id 写前置也能用）+ UnlocksRequires 里的派系名（文档写法）。
		var unlocks = new List<string> { row.Id };
		unlocks.AddRange(row.UnlockList());
		_build.SetRuneUnlocks(unlocks);

		// ③ 效果：复用既有的处理器通路（handler 拼错会在 Compile 里被点名并跳过这一行）。
		RewardDefinition? compiled = RewardEffectRegistry.Compile(row);
		if (compiled == null)
		{
			GD.PushWarning($"[Rune] 符文 {row.Id} 的 ApplyHandler「{row.ApplyHandler}」编译不出来，这一条不会生效。");
			return;
		}

		compiled.Apply(new RewardContext { Player = _player, Weapon = _weapon, Build = _runeBuild });

		_player.RefreshStats();
		GameLog.Write(
			"Rune",
			$"符文·携带：{row.Id}（{row.DisplayName}）→ 玩家生命上限 {_player.MaxHealth:0.##} / 攻击 {_player.Stats.Get("DamageMultiplier"):0.###}"
			+ $" / 受伤 ×{_player.Stats.Get("IncomingDamageMultiplier"):0.###} / 移速 ×{_player.Stats.Get("MoveSpeedMultiplier"):0.###}"
			+ $"｜解锁前置 {_build.DescribeRuneUnlocks()}");
	}

	/// <summary>特殊池尊重节点表的类型配置；其余资格与所有奖励完全一致。</summary>
	private bool OfferRareRewards(Action onChosen)
		=> TryOfferRewards(RewardNodeKind.Special, onChosen);

	/// <summary>打开一次强化三选一（商店购买、保底奖励用）。</summary>
	private bool OfferRewards()
		=> TryOfferRewards(RewardNodeKind.Enhancement, null);

	private bool TryOfferRewards(RewardNodeKind kind, Action? onChosen, NodeConfig? config = null)
		=> OfferModeReward(config == null ? RewardService.FilterFor(kind) : config.AnyRewardKind ? null : config.RewardKind,
			config == null || string.IsNullOrEmpty(config.Title) ? RewardService.TitleFor(kind) : config.Title, onChosen);

	/// <summary>模式沿用同一候选过滤与单次领取会话，不绕开前置或角色武器限定。</summary>
	public List<RewardDefinition> ModeRewardOptions(RewardKind? kind, bool preferExclusive)
	{
		EnsurePool();
		return _pool.RollMode(_build, ConfigIndex.Settings.RewardChoiceCount, kind, preferExclusive);
	}
	public bool CanOfferModeReward(RewardKind? kind, bool preferExclusive)
	{
		foreach (var row in AvailableRewards(kind)) if (preferExclusive || row.RequiredModeIds.Length == 0) return true;
		return false;
	}
	public bool OfferModeReward(RewardKind? kind, string title, Action? onChosen, bool preferExclusive = false)
	{
		if (_player == null || !IsInstanceValid(_player) || _weapon == null || _screen == null || _screen.IsOpen || _runEnded || _rewardFlow.Current?.IsPending == true)
		{
			return false;
		}

		EnsurePool();

		var options = ModeRewardOptions(kind, preferExclusive);
		if (!_rewardFlow.TryBegin(options, onChosen)) return false;
		_refreshRewardOffer = () =>
		{
			_rewardFlow.Cancel(); _screen.Close();
			if (!OfferModeReward(kind, title, onChosen, preferExclusive)) { _refreshRewardOffer = null; _player.Heal(_player.MaxHealth * .15f); onChosen?.Invoke(); }
		};
		try { _screen.Open(_rewardFlow.Current!.Options, title); }
		catch { _rewardFlow.Cancel(); _nodeRewardContext?.Cancel(); _refreshRewardOffer = null; throw; }
		return true;
	}

	public bool CompleteMode(RunModeController mode, bool victory)
	{
		if (_mode != mode || !GameplayReady || _runEnded) return false;
		EndRun(victory); return true;
	}

	/// <summary>通用多选一界面（进化池、商店等）。allowCancel = 允许 Esc 放弃（回调收到 -1）。</summary>
	public bool OpenChoice(string title, IReadOnlyList<string> options, Action<int> onChosen, bool allowCancel = false)
	{
		_chooseScreen ??= UiService.Instance?.Screen<ChooseScreen>();
		if (_chooseScreen == null || _chooseScreen.IsOpen)
		{
			return false;
		}

		_chooseScreen.AllowCancel = allowCancel;
		_chooseScreen.Open(title, options, onChosen);
		return true;
	}

	/// <summary>调试 / 验证用：当前构筑下池子里还能抽到的奖励 Id（逗号分隔）。</summary>
	public string PoolPreview
	{
		get
		{
			if (_weapon == null)
			{
				return string.Empty;
			}

			EnsurePool();

			List<RewardDefinition> list = _pool.Roll(_build, 40);
			return string.Join(",", list.ConvertAll(reward => reward.Id));
		}
	}

	/// <summary>按节点类型决定池过滤，选完之后回调（由 Stage 接着开一场 Encounter）。</summary>
	public bool OpenRewardForNode(RewardNodeKind kind, Action onChosen)
        => OpenRewardForNode(ConfigRows.ByKind<NodeConfig, RewardNodeKind>(kind) ?? new NodeConfig { Kind = kind, AnyRewardKind = RewardService.FilterFor(kind) == null, RewardKind = RewardService.FilterFor(kind) ?? RewardKind.Enhancement }, onChosen);

    public bool OpenRewardForNode(NodeConfig config, Action onChosen)
    {
        if (_player == null || !IsInstanceValid(_player) || _weapon == null || _screen == null || _screen.IsOpen || _runEnded || _nodeRewardContext?.IsPending == true) return false;
        var context = new NodeRewardContext
        {
            Player = _player, Config = config, IsActive = () => !_runEnded && IsInsideTree() && _player != null && IsInstanceValid(_player) && !_player.IsDead,
            Offer = (row, complete) => TryOfferRewards(row.Kind, complete, row),
            Choice = (title, options, selected) => OpenChoice(title, options, selected, false), OnCompleted = onChosen
        };
        _nodeRewardContext = context;
        try
        {
            bool accepted = (config.RewardBehavior ?? NodeRewardCompatibility.Behavior(config.Kind)).Begin(context);
            if (!accepted) context.Cancel(); return accepted;
        }
        catch { context.Cancel(); throw; }
    }


	private void OnRewardChosen(int index)
	{
		RewardOfferSession? offer = _rewardFlow.Current;
		if (!_runEnded && offer != null && index >= 0 && index < offer.Options.Count && !_pool.Available(_build).Exists(row => row.Id == offer.Options[index].Id))
		{
			_refreshRewardOffer?.Invoke(); return;
		}
		if (_runEnded || _player == null || !IsInstanceValid(_player) || _weapon == null || offer == null
			|| !offer.TryApply(index, definition => _build.Add(definition, new RewardContext { Player = _player, Weapon = _weapon, Build = _build }))) return;
		GameLog.Write("Reward", $"选择奖励 {offer.Selected!.Name}（{offer.Selected.Kind}）");
		bool advance = _awaitingAdvance; _awaitingAdvance = false;
		_refreshRewardOffer = null;
		_screen?.Close();
		offer.Complete();
		if (advance && !_runEnded) _stage?.Advance();
	}

	private void ResolvePlayer()
	{
		foreach (Node node in GetTree().GetNodesInGroup("player_units"))
		{
			if (node is Unit unit)
			{
				_player = unit;
				_weapon = NodeSearch.FindInSubtree<Weapon>(unit);
				return;
			}
		}
	}
}

